def hybrid_search(self, query, query_vec, k=20, rrf_k=60):
    dense_ranked  = self.dense_search(query_vec, k)   # meaning
    sparse_ranked = self.sparse_search(query, k)      # exact terms

    rrf = {}
    for rank, idx in enumerate(dense_ranked):
        rrf[idx] = rrf.get(idx, 0) + 1.0 / (rrf_k + rank + 1)
    for rank, idx in enumerate(sparse_ranked):
        rrf[idx] = rrf.get(idx, 0) + 1.0 / (rrf_k + rank + 1)

    fused = sorted(rrf.items(), key=lambda x: x[1], reverse=True)
    return [int(i) for i, _ in fused[:k]]
